function Summary({value}:{value:unknown}){const r=record(value);const currency=str(r.currency,'USD');const t=useT();return <SectionCard title="Total">{rows(r.lines).map((line,i)=><View key={str(line.id,String(i))} style={[s.row,{justifyContent:'space-between'}]}><Body>{str(line.label??line.description)} × {str(line.quantity)}</Body><MoneyText minor={line.totalMinor??line.totalAmountMinor} currency={currency}/></View>)}<MoneyText minor={r.totalMinor??r.totalAmountMinor??r.contractTotal} currency={currency} large/>{(r.depositMinor??r.depositTarget)!==undefined&&<View style={s.row}><Body>{t('Deposit')}</Body><MoneyText minor={r.depositMinor??r.depositTarget} currency={currency}/></View>}{Boolean(r.balanceDeadlineDate)&&<Body muted>{t('Balance')}: {date(r.balanceDeadlineDate)}</Body>}{Boolean(r.policySummary)&&<Body>{str(r.policySummary)}</Body>}</SectionCard>;}
