const savedListeners=new Set<()=>void>();
function useSharedSavedIds(){const [,bump]=useState(0);useEffect(()=>{const fn=()=>bump(x=>x+1);savedListeners.add(fn);return ()=>{savedListeners.delete(fn);};},[]);const toggle=(id:string)=>{const next=new Set(sharedSavedSet);if(next.has(id))next.delete(id);else next.add(id);sharedSavedSet=next;savedListeners.forEach(fn=>fn());};return {localSavedIds:sharedSavedSet,toggleLocalSaved:toggle};}
